// Laceration (wound cavity) with walls L(y), R(y); granulation grows inward from the walls,
// but stalls in the deep part where the splinter lies.
const TOP = 172, BOT = 396, CX = 232;
const half = y => { const f = (y - TOP) / (BOT - TOP); return 64 * Math.sqrt(Math.max(0, 1 - f)) * (1 - 0.25 * f) + 4; };
function wall(k, stall) {             // k: 0 = open wound, 1 = filled; stall: depth where filling stops
  const L = [], Rr = [];
  for (let y = TOP; y <= BOT; y += 4) {
    const s = 1 - api_clamp((y - (stall - 40)) / 50);            // 1 above the stall zone, 0 near splinter
    const w = half(y) * (1 - 0.94 * k * s);
    const wob = Math.sin(y * 0.11) * 2.2 * k * s;
    L.push((CX - w + wob).toFixed(1) + " " + y); Rr.push((CX + w + wob).toFixed(1) + " " + y);
  }
  return "M" + L.join(" L") + " L" + Rr.reverse().join(" L") + " Z";
}
function api_clamp(v) { return Math.max(0, Math.min(1, v)); }
let el = {};
function chip(api, g, txt, x, y, w, o) {
  const grp = api.el("g", {}, g);
  el.rects = el.rects || [];
  const r = api.el("rect", {x: x, y: y - 18, width: w, height: 36, rx: 10, fill: o.fill, stroke: o.stroke, "stroke-width": o.sw || 2}, grp);
  const t = api.el("text", {x: x + w / 2, y: y + 1, "text-anchor": "middle", "dominant-baseline": "central", "font-size": o.size || 17, "font-weight": 700, fill: o.color, "font-family": "system-ui,sans-serif"}, grp);
  t.textContent = txt; return grp;
}
function label(api, g, txt, x, y, color, anchor) {
  const t = api.el("text", {x, y, "text-anchor": anchor || "start", "dominant-baseline": "central", "font-size": 18, "font-weight": 800, fill: color, stroke: "#fff", "stroke-width": 5, "paint-order": "stroke", "stroke-linejoin": "round", "font-family": "system-ui,sans-serif"}, g);
  t.textContent = txt; return t;
}
function setup(api) {
  const lob = api.$("#fatLobules"), rnd = api.random(7);
  for (let y = 270; y < 420; y += 30) for (let x = 40 + (y % 60 ? 15 : 0); x < 410; x += 34)
    api.el("ellipse", {cx: x + rnd() * 6, cy: y + rnd() * 6, rx: 15, ry: 12}, lob);
  el.cavity = api.$("#cavity"); el.open = api.$("#open");
  api.set(el.cavity, {d: wall(0, BOT)});
  const ui = api.$("#ui");
  // beat 1: splinter callout
  el.splG = api.el("g", {}, ui);
  el.ring = api.el("ellipse", {cx: 230, cy: 399, rx: 82, ry: 26, fill: "none", stroke: "@accent", "stroke-width": 3.5, "stroke-dasharray": "8 6"}, el.splG);
  api.el("path", {d: "M262 424 L300 458", stroke: "@accent", "stroke-width": 2.5, fill: "none"}, el.splG);
  el.splLab = label(api, el.splG, "Wood splinter", 306, 466, "#c4512f");
  // beat 2: granulation label + stall label
  el.granG = api.el("g", {}, ui);
  api.el("path", {d: "M262 244 L300 222", stroke: "@good", "stroke-width": 2.5, fill: "none"}, el.granG);
  api.el("circle", {cx: 262, cy: 244, r: 4, fill: "@good", stroke: "#fff", "stroke-width": 1.5}, el.granG);
  label(api, el.granG, "Healing tissue", 304, 216, "#1d6f66");
  el.stallG = api.el("g", {}, ui);
  label(api, el.stallG, "Stalls here", 306, 356, "#c0392b");
  api.el("path", {d: "M302 362 L276 380", stroke: "#c0392b", "stroke-width": 2.5, fill: "none"}, el.stallG);
  // beat 3: local factors list
  // context: thigh from behind with the laceration on its outer side
  const leg = api.$("#leg"); el.legG = api.el("g", {}, leg.parentNode); leg.parentNode.insertBefore(el.legG, leg); el.legG.appendChild(leg);
  el.lac = api.el("g", {}, el.legG);
  api.el("circle", {cx: 545, cy: 236, r: 20, fill: "none", stroke: "@accent", "stroke-width": 3}, el.lac);
  api.el("path", {d: "M538 226 L550 246", stroke: "#a8323a", "stroke-width": 5, "stroke-linecap": "round"}, el.lac);
  label(api, el.lac, "Thigh wound", 545, 278, "#c4512f", "middle");
  el.list = api.el("g", {}, ui);
  const head = api.el("text", {x: 512, y: 176, "text-anchor": "middle", "dominant-baseline": "central", "font-size": 18, "font-weight": 800, fill: "@ink", "font-family": "system-ui,sans-serif"}, el.list);
  head.textContent = "Local factors";
  const items = ["Foreign body", "Blood clot", "Dead tissue", "Infection", "Hypoxia", "Poor blood supply"];
  el.chips = items.map((s, i) => chip(api, el.list, s, 420, 220 + i * 48, 184,
    i === 0 ? {fill: "#fff1ec", stroke: "@accent", color: "#b23a1e", sw: 3, size: 18} : {fill: "#f3f7f7", stroke: "#dbe6e7", color: "#5f7a80", size: 17}));
  el.link = api.el("path", {d: "M418 220 C 360 230, 330 300, 300 392", fill: "none", stroke: "@accent", "stroke-width": 3, "stroke-dasharray": "7 6", "stroke-linecap": "round"}, ui);
}
function vis(api, node, o) { api.set(node, {opacity: o.toFixed(3), display: o > 0.001 ? "inline" : "none"}); }
function render(t, api) {
  // 1. splinter flagged
  const a = api.seg(t, 150, 700, "ease_out") * (1 - api.seg(t, 4600, 4900));
  vis(api, el.splG, a);
  // 2. granulation fills in from the walls, but not around the splinter
  const k = api.seg(t, 2400, 4300, "ease_in_out");
  api.set(el.open, {d: wall(k, 372)});
  const hot = api.seg(t, 2600, 3400, "ease_out");
  const pulse = 0.85 + 0.15 * Math.sin(t / 260);
  api.set(api.$("#hotzone"), {opacity: (hot * (t < 3400 ? 1 : pulse)).toFixed(3)});
  vis(api, el.granG, api.seg(t, 2900, 3400) * (1 - api.seg(t, 4600, 4800)));
  vis(api, el.stallG, api.seg(t, 3500, 3900) * (1 - api.seg(t, 4600, 4800)));
  // 3. local factors list, foreign body highlighted
  vis(api, el.legG, 1 - api.seg(t, 4600, 4800));
  vis(api, el.list, api.seg(t, 4650, 5000));
  el.chips.forEach((c, i) => { const f = api.seg(t, 4700 + i * 110, 5050 + i * 110, "ease_out");
    vis(api, c, f); api.set(c, {transform: "translate(" + ((1 - f) * 20).toFixed(1) + " 0)"}); });
  const d = api.seg(t, 5100, 5600, "ease_out");
  api.set(el.link, {"stroke-dashoffset": 0, opacity: d.toFixed(3), display: d > 0 ? "inline" : "none"});
}
